import { Component, OnDestroy, OnInit, ViewChild } from '@angular/core';
import { DatePickerComponent, DefaultsService, GovBrDatePickerModule, GovBrInputModule, GovBrSelectModule} from '@serpro/ngx-dsgovbr';
import { CommonModule } from '@angular/common';
import { TooltipModule } from 'ngx-bootstrap/tooltip';
import { FormBuilder, FormGroup, ReactiveFormsModule, Validators } from '@angular/forms';
import { DadosAbertosService } from '../../../services/dados-abertos.service';
import { ConsultarAliquotasResultadoComponent } from '../consultar-aliquotas-resultado/consultar-aliquotas-resultado.component';
import { MensagemService } from '../../../services/mensagem.service';

@Component({
  selector: 'consultar-aliquotas-uniao',
  templateUrl: './consultar-aliquotas-uniao.component.html',
  styleUrl: './consultar-aliquotas-uniao.component.scss',
  standalone: true,
  imports: [
    CommonModule,
    ReactiveFormsModule,
    TooltipModule,
    GovBrDatePickerModule,
    GovBrSelectModule,
    GovBrInputModule,
    ConsultarAliquotasResultadoComponent
  ],
  providers: [],
})
export class ConsultarAliquotasUniaoComponent implements OnInit, OnDestroy {

  @ViewChild('datePicker') datePicker: DatePickerComponent | undefined;

  response: any = null;

  form!: FormGroup;

  constructor(
    private readonly dadosAbertosService: DadosAbertosService,
    private readonly formBuilder: FormBuilder,
    private readonly defaultsService: DefaultsService,
    private readonly mensagemService: MensagemService
  ) { }

  ngOnInit(): void {
    this.defaultsService.labelRequired = '';
    this.form = this.formBuilder.group({
      dataControl: [new Date(), [Validators.required]],
    });
  }

  resetarValores() {
    this.response = null;
  }

  dataControlChange(event: any) {
    this.resetarValores();
  }

  dataControlInputChange(event: any) {
    this.resetarValores();
    if (event.srcElement.value.length >= 10) {
      this.datePicker?.selectionInlineDone(new Date(event.srcElement.value));
    }
  }

  ngOnDestroy(): void {
    //this.subscriptions.unsubscribe();
    this.mensagemService.limpar();
  }

  consultar() {
    this.resetarValores();
    let data = this.form.get('dataControl')?.value;
    if (this.form.valid) {
      this.dadosAbertosService.consultarAliquotasUniao(data).subscribe({
        next: (data) => {
          this.response = data.body;
          let header = data.headers.get('x-warning-dados-simulados') || null;
          if (!header) {
            this.mensagemService.mostrar('Sucesso', 'Sucesso', 'Consulta realizada com sucesso.');
          }
          if (header) {
            this.mensagemService.mostrar('Aviso', 'Aviso', this.obterAviso(header));
          }
        },
        error: (error) => {
          this.mensagemService.mostrar('Erro', 'Erro', 'Erro ao realizar a consulta: ' + error?.message);
        }
      });
    }
  }

  AVISOS: { [key: string]: string } = {
    '0': '',
    '1': 'Para a data selecionada, as alíquotas da CBS ainda não possuem valores definidos em lei. Os valores exibidos são provisórios e devem ser utilizados apenas para fins de testes.',
    '2': '',
    '3': '',
    '4': '',
    '5': ''
  };

  obterAviso(header: any): string {

    if (!header) {
      return '';
    }
    const headerKey = String(header);
    return this.AVISOS[headerKey] || '';
  }

}
